  return makeCanvas(256, (g, s) => {
    g.fillStyle = '#9a7748';
    g.fillRect(0, 0, s, s);
    // grain
    for (let i = 0; i < 90; i++) {
      g.strokeStyle = `rgba(${60 + Math.random() * 40},${42 + Math.random() * 26},20,${0.10 + Math.random() * 0.18})`;
      g.lineWidth = 1 + Math.random() * 2;
