    g.fillStyle = '#5d6660';
    g.fillRect(0, 0, s, s);
    speckle(g, s, 3000, 0.10, true);
    // rust patches
    for (let i = 0; i < 9; i++) {
      const grad = g.createRadialGradient(
        Math.random() * s, Math.random() * s, 2,
        Math.random() * s, Math.random() * s, 14 + Math.random() * 36);
