// ---------- World construction ----------
const WALL_H = 4;

export function buildWorld(scene) {
  const colliders = [];          // THREE.Box3 for movement collision
  const solids = new THREE.Group(); // meshes for bullet/vision raycasts
  solids.name = 'solids';
  scene.add(solids);

  const floorTex = concreteTexture();
  floorTex.repeat.set(20, 15);
  const wallTex = plasterTexture();
  const woodTex = plywoodTexture();
  const metalTex = metalTexture();

  const floorMat = new THREE.MeshStandardMaterial({ map: floorTex, bumpMap: floorTex, bumpScale: 0.06, roughness: 0.93, metalness: 0.02 });
  const wallMat  = new THREE.MeshStandardMaterial({ map: wallTex, bumpMap: wallTex, bumpScale: 0.05, roughness: 0.9 });
  const woodMat  = new THREE.MeshStandardMaterial({ map: woodTex, bumpMap: woodTex, bumpScale: 0.05, roughness: 0.85 });
  const metalMat = new THREE.MeshStandardMaterial({ map: metalTex, bumpMap: metalTex, bumpScale: 0.04, roughness: 0.55, metalness: 0.65 });
  const ceilMat  = new THREE.MeshStandardMaterial({ color: 0x3c4042, roughness: 0.95 });

  // Floor
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(40, 30), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);
  solids.add(floor.clone());

  // Ceiling with a skylight gap in the middle (sun comes through)
  for (const [x, z, w, d] of [
    [0, -11, 40, 8], [0, 11, 40, 8], [-14, 0, 12, 14], [14, 0, 12, 14],
  ]) {
    const ceil = new THREE.Mesh(new THREE.PlaneGeometry(w, d), ceilMat);
    ceil.rotation.x = Math.PI / 2;
    ceil.position.set(x, WALL_H, z);
    scene.add(ceil);
  }

  function wall(cx, cz, w, d, mat = wallMat, h = WALL_H, y = 0) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    if (mat === wallMat) {
      const t = wallTex.clone();
      t.needsUpdate = true;
      t.repeat.set(Math.max(w, d) / 3, h / 3);
      m.material = wallMat.clone();
      m.material.map = t;
      m.material.bumpMap = t;
    }
    m.position.set(cx, y + h / 2, cz);
    m.castShadow = m.receiveShadow = true;
    scene.add(m);
    solids.add(m.clone());
    colliders.push(new THREE.Box3().setFromObject(m));
    return m;
  }

  // Perimeter (slightly thick)
  wall(0, -15.2, 40.8, 0.4);            // north
  wall(0, 15.2, 40.8, 0.4);             // south
  wall(-20.2, 0, 0.4, 30.8);            // west
  wall(20.2, 0, 0.4, 30.8);             // east

  // --- Interior rooms (gaps are doorways) ---
  // NW room: wall along x=-6 (z -15..-5), door at z≈-9
  wall(-6, -12.5, 0.4, 5);   // z -15..-10
  wall(-6, -6.5, 0.4, 3);    // z -8..-5
  // NW room south wall: z=-5 (x -20..-6), door at x≈-14
  wall(-17.5, -5, 5, 0.4);   // x -20..-15
  wall(-9.5, -5, 7, 0.4);    // x -13..-6

  // NE room: wall along x=8 (z -15..-4), door at z≈-7
  wall(8, -11.5, 0.4, 7);    // z -15..-8
  wall(8, -5, 0.4, 2);       // z -6..-4
  // NE room south wall: z=-4 (x 8..20), door at x≈15
  wall(11, -4, 6, 0.4);      // x 8..14
  wall(18, -4, 4, 0.4);      // x 16..20

  // SW room: wall along z=6 (x -20..-8), door at x≈-13
  wall(-17, 6, 6, 0.4);      // x -20..-14
  wall(-10, 6, 4, 0.4);      // x -12..-8
  // SW room east wall: x=-8 (z 6..15), door at z≈11
  wall(-8, 8, 0.4, 4);       // z 6..10
  wall(-8, 13.5, 0.4, 3);    // z 12..15

  // SE room: wall along x=4 (z 5..15), door at z≈10
  wall(4, 7, 0.4, 4);        // z 5..9
  wall(4, 13, 0.4, 4);       // z 11..15
  // SE room north wall: z=5 (x 4..20), door at x≈12
  wall(7.5, 5, 7, 0.4);      // x 4..11
  wall(16.5, 5, 7, 0.4);     // x 13..20

  // Central half-wall cover (chest height) in the main hall
  wall(0, 0, 6, 0.5, wallMat, 1.2);
  wall(-3, -8, 0.5, 5, wallMat, 1.2);

  // --- Crates & barrels (cover) ---
  function crate(x, z, size = 1.2, y = 0) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(size, size, size), woodMat);
    m.position.set(x, y + size / 2, z);
    m.rotation.y = Math.random() * 0.6 - 0.3;
    m.castShadow = m.receiveShadow = true;
    scene.add(m);
    solids.add(m.clone());
    colliders.push(new THREE.Box3().setFromObject(m));
  }
  function barrel(x, z) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 1.1, 14), metalMat);
    m.position.set(x, 0.55, z);
    m.castShadow = m.receiveShadow = true;
    scene.add(m);
    solids.add(m.clone());
    colliders.push(new THREE.Box3().setFromObject(m));
  }

  crate(2.5, -2.5); crate(2.5, -1.2, 1.0); crate(2.9, -2.3, 0.9, 1.2);
  crate(-12, 1); crate(-11, 1.8, 1.0);
  crate(16, 9); crate(15, 10.1, 1.0); crate(16.2, 9.2, 0.8, 1.2);
  crate(-16, -10); crate(12, -10); crate(12.8, -8.9, 0.9);
  crate(-3, 11); crate(-2, 11.6, 0.9);
  barrel(5.5, 1.5); barrel(6.2, 2.3); barrel(-7, -2);
  barrel(-15, 11); barrel(18, -7); barrel(18.8, -6.2);

  // --- Lighting ---
  scene.background = new THREE.Color(0x10141a);
  scene.fog = new THREE.FogExp2(0x10141a, 0.014);

  const hemi = new THREE.HemisphereLight(0x8fa3bf, 0x3a3630, 0.55);
  scene.add(hemi);

  const sun = new THREE.DirectionalLight(0xfff2dd, 2.6);
  sun.position.set(6, 18, 4);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -24; sun.shadow.camera.right = 24;
  sun.shadow.camera.top = 20; sun.shadow.camera.bottom = -20;
  sun.shadow.camera.near = 2; sun.shadow.camera.far = 50;
  sun.shadow.bias = -0.0004;
  scene.add(sun);

  // Warm interior work lamps
  const lampPositions = [[-13, -10], [14, -9], [-14, 10.5], [12, 10], [0, -8]];
  for (const [x, z] of lampPositions) {
    const lamp = new THREE.PointLight(0xffc890, 14, 16, 1.8);
    lamp.position.set(x, 3.4, z);
    scene.add(lamp);
    const bulb = new THREE.Mesh(
      new THREE.SphereGeometry(0.09, 8, 8),
      new THREE.MeshBasicMaterial({ color: 0xffd9a8 }));
    bulb.position.copy(lamp.position);
    scene.add(bulb);
  }

  // Dust motes drifting in the skylight shaft
  const dustGeo = new THREE.BufferGeometry();
  const dustCount = 250;
  const pos = new Float32Array(dustCount * 3);
  for (let i = 0; i < dustCount; i++) {
    pos[i * 3] = (Math.random() - 0.5) * 14 - 2;
    pos[i * 3 + 1] = Math.random() * 4;
    pos[i * 3 + 2] = (Math.random() - 0.5) * 12;
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
    color: 0xfff0d8, size: 0.02, transparent: true, opacity: 0.5, depthWrite: false,
  }));
  scene.add(dust);

  // Enemy spawn definitions: position + patrol waypoints
  const enemySpawns = [
    { pos: [-13, -10], waypoints: [[-13, -10], [-17, -7], [-8, -12]] },
    { pos: [14, -9],   waypoints: [[14, -9], [11, -13], [18, -6]] },
    { pos: [12, -1],   waypoints: [[12, -1], [16, 2], [10, -2]] },
